insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tz', '/flags/history/tz-1856.svg', '1856-10-19', '1963-12-10', 'Sultanat de Zanzibar', 'Sultanate of Zanzibar', 'Le sultanat né de la partition de l''empire omanais arbore un simple drapeau rouge ; il devient protectorat britannique en 1890.', 'The sultanate born from the split of the Omani empire flew a plain red flag; it became a British protectorate in 1890.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tz', '/flags/history/tz-1923.svg', '1923-01-01', '1961-12-09', 'Territoire du Tanganyika', 'Tanganyika Territory', 'Ancienne Afrique orientale allemande confiée au Royaume-Uni par la Société des Nations : Blue Ensign à la tête de girafe.', 'Former German East Africa entrusted to Britain by the League of Nations: a Blue Ensign with a giraffe''s head.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tz', '/flags/history/tz-1963.svg', '1963-12-10', '1964-01-12', 'Zanzibar indépendant', 'Independent Zanzibar', 'Drapeau du sultanat devenu indépendant le 10 décembre 1963, renversé un mois plus tard par la révolution de Zanzibar.', 'Flag of the sultanate, independent from 10 December 1963 and overthrown a month later by the Zanzibar Revolution.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tz', '/flags/history/tz-1964.svg', '1964-01-12', '1964-04-26', 'République populaire de Zanzibar', 'People''s Republic of Zanzibar', 'Après la révolution, la république de Zanzibar s''unit au Tanganyika le 26 avril 1964 pour former la Tanzanie.', 'After the revolution, the republic of Zanzibar united with Tanganyika on 26 April 1964 to form Tanzania.');
